exercises.solutionCode:
#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int* values = malloc(3 * sizeof *values);
    if (values == NULL) return 1;
    values[0] = 7;
    printf("%d\n", values[0]);
    free(values);
}

exercises.starterCode:
#include <stdio.h>
int main(void) {
    /* Open notes.txt, count its lines, then close it. */
}

exercises.solutionCode:
#include <stdio.h>
int main(void) {
    FILE* file = fopen("notes.txt", "r");
    if (file == NULL) return 1;
    int ch, last = EOF, lines = 0;
    while ((ch = fgetc(file)) != EOF) {
        if (ch == '\n') lines++;
        last = ch;
    }
    if (ferror(file)) { fclose(file); return 1; }
    if (last != EOF && last != '\n') lines++;
    fclose(file);
    printf("%d\n", lines);
}
